// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount, uint256 sendValue, address target) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(amount >= sendValue);
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(target, sendValue) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
